import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./braces-B2_rnCwm.js";import{C as n,D as r,M as i,N as a,O as o,P as s,S as c,T as l,b as u,h as d,j as f,k as p,v as m}from"./shared-DP9JVsk0.js";import{O as h}from"./index-DLaUeCZy.js";import{t as g}from"./CodeEditor-BZlrvoTL.js";var _=`data:image/svg+xml;base64,`,v=`data:image/svg+xml;base64,`,y=e();function b({module:e}){let b=`class RegionInput(BaseModel):
    code: str

    @field_validator("code", mode="before")
    @classmethod
    def normalize_code(cls, value: object) -> object:
        if isinstance(value, str):
            return value.strip().upper()
        return value`;return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{variant:`project`,chip:e??`Блок 11 · Валидация и CRUD Planner API`,title:`Pydantic-валидация и ошибка 422`,intro:`Предыдущий шаг уже связал запрос с существующим Planner. Теперь проверим, как остановить неподходящие данные до действия, не переписывая работающий POST.`,tags:[{icon:(0,y.jsx)(t,{size:14}),label:`вход до endpoint`},{icon:(0,y.jsx)(h,{size:14}),label:`проверка и сохранение`}]}),(0,y.jsxs)(s,{number:`00`,title:`От настоящего POST к точным правилам входа`,children:[(0,y.jsx)(o,{children:`Посмотрим, что происходит, когда JSON прочитать можно, но значения в нём не подходят приложению.`}),(0,y.jsx)(p,{variant:`connected`,items:[{title:`Точка старта`,description:`Проверенный запрос создаёт Task через PlannerService, а JsonStorage сохраняет её в общем файле.`},{title:`Новый вопрос`,description:`Как не пропустить неподходящее название или приоритет к действию, не переписывая работающий POST?`},{title:`Результат`,description:`Уточним TaskCreate: очистим title, проверим его длину и диапазон priority; ошибочный body остановится до endpoint.`}]}),(0,y.jsx)(`p`,{children:`Проверка входа похожа на контроль перед посадкой: билет должен быть читаемым, а пассажир и рейс должны соответствовать правилам. Проверка билета ещё не перевозит пассажира. Так же и Pydantic готовит допустимые данные, но сам не создаёт и не сохраняет задачу.`}),(0,y.jsx)(`p`,{children:`Сначала разберём его проверки на независимой форме отзыва, потом проследим путь Planner. Так предыдущая операция остаётся нашей опорой, а не превращается в задачу на повторное создание.`})]}),(0,y.jsxs)(s,{number:`01`,title:`JSON можно прочитать, но данные ещё не подходят`,children:[(0,y.jsx)(o,{children:`JSON-парсер отвечает, можно ли прочитать сообщение. Pydantic отвечает на следующий вопрос: можно ли построить из разобранных значений объект заданной входной модели.`}),(0,y.jsx)(`p`,{children:`Например, объект с title из пробелов и priority=4 синтаксически является корректным JSON. Но после очистки название станет пустым. Тип str сам по себе не описывает это правило. Валидация проверяет форму и простые ограничения входа; предметные правила задачи по-прежнему принадлежат модели и сервису Planner.`}),(0,y.jsx)(`p`,{children:`В FastAPI проверка body происходит до вызова функции endpoint. Поэтому невалидный TaskCreate не попадает в обработчик, не вызывает add_task и не доходит до сохранения. Эта граница подходит для обязательных полей, типов и простых пределов, но не переносит туда весь алгоритм проекта. Ответ 422 Unprocessable Entity сообщает, что сервер прочитал сообщение, но не может принять его значения по объявленному контракту. Это не исключение Python и не указание на то, что FastAPI сломался. Для клиента это сигнал исправить вход; в Planner при этом не создаётся ресурс.`}),(0,y.jsx)(`p`,{children:`При обычной конфигурации Pydantic выполняет разрешённые преобразования типов: например, строку «4» может разобрать как целое число. Это не отменяет границы priority и не включает строгий режим. Тип задаёт ожидаемую форму значения, Field задаёт предел, а схема соединяет эти правила. Мы не добавляем strict=True без такого требования в договоре.`}),(0,y.jsx)(u,{question:`Что произойдёт с body без priority?`,options:[`Pydantic не построит обязательную модель, FastAPI вернёт 422 до endpoint`,`Planner создаст задачу с приоритетом по умолчанию`,`Endpoint начнётся, но проигнорирует только priority`],correctIndex:0,explanation:`Поле без значения по умолчанию обязательно. FastAPI не передаёт в endpoint частично построенную TaskCreate и не должен выдумывать отсутствующий priority.`}),(0,y.jsx)(`p`,{children:`Так мы отделяем разбор транспортного формата от смысла значения. Успешный разбор JSON ещё не означает, что клиентское значение подходит правилам API.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Field задаёт границы, но не меняет значение`,children:[(0,y.jsx)(o,{children:`Аннотация задаёт ожидаемый тип, а Field описывает простые пределы рядом с полем. Эти два указания дополняют друг друга.`}),(0,y.jsx)(`p`,{children:`В независимой форме отзыва комментарий должен иметь длину от 2 до 80 символов, а оценка лежать между 1 и 5 включительно. Для чисел используются ge, «больше или равно», и le, «меньше или равно». Для строки min_length и max_length задают длину. Обе границы входят в допустимый диапазон.`}),(0,y.jsx)(g,{caption:`ограничения независимой формы`,code:`class SurveyInput(BaseModel):
    comment: str = Field(min_length=2, max_length=80)
    score: int = Field(ge=1, le=5)`}),(0,y.jsx)(`p`,{children:`Field измеряет значение на своём этапе и не исправляет его. Три пробела имеют длину три, поэтому одна проверка min_length=1 их пропустит. Если важен смысл строки, перед ограничением нужна отдельная нормализация.`}),(0,y.jsx)(`p`,{children:`В FastAPI эти ограничения также становятся частью описания body в OpenAPI и Swagger UI. Это помогает увидеть договор запроса, но не проверяет форму на устройстве клиента: решающее отклонение всё равно выполняет сервер. Field и документация не делают title необязательным, потому что у поля нет значения по умолчанию.`}),(0,y.jsx)(`p`,{children:`Представим линейку и карандаш: Field измеряет уже предъявленную длину, но не стирает лишние отметки по краям. Проверка значения и его подготовка решают разные задачи. В Planner мы сперва уберём внешние пробелы, а затем проверим, что итоговый title содержит от 1 до 120 символов. priority примет значение от 1 до 5 включительно.`}),(0,y.jsx)(c,{statement:(0,y.jsx)(`span`,{children:`Field(min_length=1) самостоятельно превращает строку из пробелов в пустое значение.`}),isTrue:!1,explanation:`Field проверяет длину текущего значения и не вызывает strip. Строка из пробелов имеет ненулевую длину, пока отдельный шаг нормализации её не очистил.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Before-validator готовит исходное значение`,children:[(0,y.jsx)(o,{children:`В Pydantic v2 field_validator с режимом before запускается до обычной проверки поля. Здесь можно нормализовать значение, а после этого передать результат проверке типа и Field.`}),(0,y.jsx)(`p`,{children:`Рассмотрим независимый пример: форма получает код региона, который в системе должен храниться заглавными буквами без внешних пробелов.`}),(0,y.jsx)(g,{caption:`подготовка кода региона`,code:b}),(0,y.jsx)(`p`,{children:`Валидатор принимает object, потому что на этом этапе нельзя заранее считать исходное значение строкой. Проверка isinstance разрешает вызывать строковые методы только для строки. Число возвращается без изменения; затем Pydantic сам формирует ошибку типа. Так мы избегаем AttributeError, который возник бы при безусловном вызове strip. field_validator помечает метод модели как проверку конкретного поля, а classmethod передаёт ему класс схемы. Pydantic вызывает метод при построении модели; мы не запускаем его вручную в endpoint. Валидатор возвращает подготовленную строку или исходный объект для следующего шага и не создаёт побочных действий в Planner.`}),(0,y.jsx)(`p`,{children:`Валидатор должен вернуть значение: нормализованную строку или исходный объект для последующей проверки. Он не вызывает PlannerService и не записывает файл. Это сохраняет границу схемы: она готовит вход, а действие начинается позже. Тип object честно показывает, что сырое значение ещё не прошло обычную проверку str.`}),(0,y.jsx)(`p`,{children:`Представим сортировочный стол: один этап убирает упаковку, но не меняет содержимое предмета, а следующий контролёр решает, подходит ли оно по размеру и типу. Сравнение помогает увидеть границу: нормализация и проверка идут последовательно, но выполняют разные обязанности.`}),(0,y.jsx)(m,{code:b,steps:[{line:0,note:`Pydantic получает исходные данные формы.`,vars:{code:`«  nw  »`}},{line:3,note:`Before-validator запускается до обычной проверки строки.`},{line:6,note:`Проверяется, что исходное значение является строкой.`},{line:7,note:`Строка очищается и приводится к верхнему регистру.`,vars:{value:`«  nw  »`,result:`«NW»`}},{line:8,note:`Другой тип возвращается без изменения для проверки Pydantic.`,vars:{value:`42`}},{line:8,note:`Pydantic проверяет результат и создаёт RegionInput.`,vars:{code:`«NW»`}}]}),(0,y.jsx)(`p`,{children:`Для числа последовательность почти та же, но ветка нормализации пропускается: валидатор возвращает число, а последующая проверка типа отклоняет его. Важно, что до этой проверки не вызывается метод строки.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Нормализовать, затем ограничить`,children:[(0,y.jsx)(o,{children:`Ограничения должны проверять название, которое действительно останется в Planner, а не временные пробелы вокруг него.`}),(0,y.jsx)(`p`,{children:`Если измерить исходную строку, внешние пробелы увеличат её длину. Если сначала очистить её, Field увидит итоговый title. Значения проходят по разным веткам, и мы можем проследить результат каждой.`}),(0,y.jsx)(d,{code:`if isinstance(value, str):
    return value.strip()
return value`,scenarios:[{label:`value = « API »`,activeLine:1,output:`«API» проходит проверку длины`},{label:`value = «   »`,activeLine:1,output:`Пустая строка не проходит min_length=1`},{label:`value = 42`,activeLine:2,output:`Число остаётся прежним; Pydantic проверяет тип`}]}),(0,y.jsx)(`p`,{children:`Для TaskCreate это означает: «  API  » превращается в «API»; строка только из пробелов становится пустой и не проходит min_length=1; название длиннее 120 символов после очистки не проходит max_length=120. Для priority допустимы 1 и 5, а 0 и 6 находятся за границами.`}),(0,y.jsx)(n,{code:`class TaskCreate(BaseModel):
    title: str

    @field_validator("title", mode="before")
    @classmethod
    def strip_title(cls, value: object) -> object:
        return value.strip()`,question:`Почему это опасная проверка входа?`,options:[`value может быть числом, и strip вызовет AttributeError до проверки типа`,`mode=before запрещает возвращать строки`,`Pydantic автоматически обрежет title дважды`],correctIndex:0,explanation:`Before-validator получает сырое значение. Сначала проверяем isinstance(value, str); строку очищаем, а другой тип возвращаем Pydantic без изменений.`,fix:`if isinstance(value, str):
            return value.strip()
        return value`}),(0,y.jsx)(l,{question:`Какое сочетание проверит очищенный title длиной от 1 до 120?`,left:{title:`Только Field`,code:`title: str = Field(min_length=1, max_length=120)`,note:`Пробельная строка имеет длину и может пройти минимальную границу.`},right:{title:`Before и Field`,code:`Сначала strip для строки, затем Field(min_length=1, max_length=120)`,note:`Field получает нормализованное значение и проверяет итоговую длину.`},preferred:`right`,explanation:`Field не очищает текст, а before-validator сам по себе не задаёт предел. Здесь нужны оба шага в правильном порядке.`}),(0,y.jsx)(`p`,{children:`У 422 есть два возможных этапа. FastAPI возвращает его, когда не удаётся построить body до вызова маршрута. Другой уже знакомый путь появляется, если endpoint вызвал PlannerService, получил ожидаемый ValueError и преобразовал его в HTTPException(422). Код ответа совпадает, но место и причина отказа различаются.`}),(0,y.jsx)(`p`,{children:`В подробностях ответа обычно есть loc с участком body и именем поля. Формулировка msg зависит от версии Pydantic, поэтому мы разбираем поле и правило, а не фиксируем весь английский текст. Сбой JsonStorage не является ошибкой входа: его нельзя маскировать под 422 или 404. Проверка body до endpoint доказывает, что сервис не вызван именно при этом отказе; она не обещает откат файла при произвольной ошибке записи.`}),(0,y.jsx)(`p`,{children:`Поле loc помогает отличить пропущенный priority от неверного title: например, путь может указывать на body и соответствующее имя. Детали msg и type полезны при чтении ответа, но текст msg меняется между версиями библиотек, поэтому тесты не должны закреплять его дословно. Это и есть задача чтения ошибки: связать участок запроса с уже объяснённым правилом. Для собственной HTTPException поле detail может быть строкой; ошибка Pydantic обычно содержит список элементов. Мы различаем эти ответы по структуре и месту отказа, а не по одному статусу.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Planner продолжает создавать настоящую задачу`,children:[(0,y.jsx)(o,{children:`Мы уточняем вход существующего POST, а не строим вторую операцию создания или новый источник данных.`}),(0,y.jsx)(`p`,{children:`TaskCreate содержит поля title и priority. Идентификатор и начальный статус остаются на стороне сервера. Мы не включаем настройку extra=forbid: при стандартной конфигурации неизвестные ключи не обязаны давать отдельный 422, поэтому такой результат не обещаем. Маршрут передаёт сервису только объявленные значения.`}),(0,y.jsx)(`p`,{children:`TaskCreate защищает конкретную HTTP-границу, но не заменяет правила доменной Task. PlannerService может вызываться и через CLI, где эта схема вообще не участвует. Поэтому сервис и модель сохраняют свои проверки, а новая схема добавляет ранний ответ для сетевого клиента. Ограничения API здесь не становятся незаметным изменением командной строки.`}),(0,y.jsx)(`p`,{children:`После успешной проверки endpoint вызывает прежний PlannerService. Сервис создаёт доменную Task и сохраняет её через общий JsonStorage; API возвращает публичную проекцию с кодом 201. Входная схема и её словарь не являются сохранённой Task. Внутренняя модель и файл остаются прежними, включая непубличные данные проекта.`}),(0,y.jsx)(g,{caption:`неизменённый путь успешного POST`,code:`@app.post("/tasks", status_code=201)
def create_task(payload: TaskCreate):
    task = app.state.planner.add_task(
        payload.title,
        priority=payload.priority,
    )
    return {
        "id": task.id,
        "title": task.title,
        "priority": task.priority,
        "is_done": task.is_done,
    }`}),(0,y.jsxs)(`figure`,{className:`lesson-infographic lesson-infographic--lesson57`,children:[(0,y.jsxs)(`picture`,{children:[(0,y.jsx)(`source`,{media:`(max-width: 640px)`,srcSet:v}),(0,y.jsx)(`img`,{src:_,alt:`JSON body проходит через TaskCreate: before-validator очищает строку, затем Field проверяет границы. Допустимые данные доходят до endpoint, PlannerService и JsonStorage. Ошибка проверки останавливается до endpoint; после сохранения API возвращает 201.`,width:1672,height:836,loading:`lazy`,decoding:`async`})]}),(0,y.jsx)(`figcaption`,{children:`Очистка и ограничения стоят перед действием, а успешный POST продолжает общий путь Planner.`})]}),(0,y.jsx)(`p`,{children:`На схеме отказ входной проверки расположен до endpoint, поэтому не вызывает add_task. При успехе тот же запрос проходит через сервис и файл. Если файловая запись завершится с ошибкой, этот урок не обещает автоматического отката или восстановления.`}),(0,y.jsx)(`p`,{children:`Мы сравниваем список, stats и рабочий JSON до и после отказа body. Для успешного POST берём фактический id, читаем запись через GET /tasks/{task_id}, сверяем результат с CLI и повторяем чтение после перезапуска API. Так проверяются отдельно ранний отказ и постоянство успешного результата.`})]}),(0,y.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`Применим границы к настоящему POST и проверим, что они оставляют прежний Planner в согласованном состоянии.`}),(0,y.jsx)(p,{variant:`connected`,items:[{title:`Уточним TaskCreate`,description:`Очистим title до проверки длины от 1 до 120 символов и ограничим priority значениями от 1 до 5.`},{title:`Сверим границы`,description:`Проверим обязательность, типы, допустимые края и ошибки 422, разбирая проблемное поле.`},{title:`Подтвердим путь`,description:`Сравним состояние при отказе и прочитаем успешно созданную запись через API и CLI.`}]}),(0,y.jsx)(`p`,{children:`Практика продолжает реальное создание из предыдущего занятия. Она не меняет endpoint, PlannerService, Task, формат JSON или публичный ответ. Ошибка body не добавляет задачу; допустимое значение проходит прежний POST и сохраняется очищенным.`}),(0,y.jsx)(`p`,{children:`В следующем занятии мы разделим схему входа и публичный ответ, сохранив получившиеся правила TaskCreate.`}),(0,y.jsx)(r,{points:[(0,y.jsx)(y.Fragment,{children:`Field проверяет пределы, но не выполняет нормализацию.`}),(0,y.jsx)(y.Fragment,{children:`Before-validator подготавливает исходную строку до стандартной проверки типа и ограничений.`}),(0,y.jsx)(y.Fragment,{children:`Невалидный body останавливается до endpoint; ожидаемая ошибка сервиса возникает позже.`}),(0,y.jsx)(y.Fragment,{children:`Успешное создание по-прежнему проходит через один PlannerService и общий JsonStorage.`})]}),(0,y.jsx)(f,{text:`Уточните TaskCreate и проверьте границы POST на настоящем Planner.`})]})]})}export{b as Lesson57};